#include <stdio.h>

// Period parameters:
#define TINYMT32_MEXP 127
#define TINYMT32_SH0 1
#define TINYMT32_SH1 10
#define TINYMT32_SH8 8
#define TINYMT32_MASK ((unsigned int)0x7fffffff)
#define TINYMT32_MUL (1.0f / 4294967296.0f)
#define MIN_LOOP 8
#define PRE_LOOP 8

#define MAT1 0x8F7011EE
#define MAT2 0xFC78FF1F
#define TMAT 0x3793FDFF

typedef struct {
	unsigned int state[4];
	unsigned int mat1;
	unsigned int mat2;
	unsigned int tmat;
} tinymt32_t;

static tinymt32_t random;

/**
* This function represents a function used in the initialization
* by init_by_array.
*
* ## Notes
*
* -   Used for initialization of the internal state array.
*
* @param x  32-bit integer
* @return 32-bit integer
*/
static unsigned int ini_func1(unsigned int x) {
	return (x ^ (x >> 27)) * (unsigned int)1664525UL;
}

/**
* This function represents a function used in the initialization
* by init_by_array.
*
* ## Notes
*
* -   Used for initialization of the internal state array.
*
* @param x  32-bit integer
* @return 32-bit integer
*/
static unsigned int ini_func2(unsigned int x) {
	return (x ^ (x >> 27)) * (unsigned int)1566083941UL;
}

/**
* This function changes internal state of tinymt32.
*
* ## Notes
*
* -   Users should not call this function directly.
*
*/
inline static void tinymt32_next_state() {
	unsigned int x;
	unsigned int y;

	y = random.state[3];
	x = (random.state[0] & TINYMT32_MASK)
		^ random.state[1]
		^ random.state[2];
	x ^= (x << TINYMT32_SH0);
	y ^= (y >> TINYMT32_SH0) ^ x;
	random.state[0] = random.state[1];
	random.state[1] = random.state[2];
	random.state[2] = x ^ (y << TINYMT32_SH1);
	random.state[3] = y;
	int const a = -((int)(y & 1)) & (int)random.mat1;
	int const b = -((int)(y & 1)) & (int)random.mat2;
	random.state[1] ^= (unsigned int)a;
	random.state[2] ^= (unsigned int)b;
}

/**
* This function outputs 32-bit unsigned integer from internal state.
*
* ## Notes
*
* -   Users should not call this function directly.
*
* @return 32-bit unsigned pseudorandom number
*/
inline static unsigned int tinymt32_temper() {
	unsigned int t0, t1;
	t0 = random.state[3];
	t1 = random.state[0]
		+ (random.state[2] >> TINYMT32_SH8);
	t0 ^= t1;

	if ((t1 & 1)) {
		t0 ^= random.tmat;
	}
	return t0;
}

/**
* This function initializes the internal state array with a 32-bit
* unsigned integer seed.
*
* ## Notes
*
* -   See Knuth TAOCP Vol2. 3rd Ed. P.106 for multiplier.
*
* @param seed    a 32-bit unsigned integer used as a seed
*/
void init_genrand(unsigned int seed) {
	// Initialize constants:
	random.mat1 = MAT1;
	random.mat2 = MAT2;
	random.tmat = TMAT;

	// Initialize state:
	random.state[0] = seed;
	random.state[1] = random.mat1;
	random.state[2] = random.mat2;
	random.state[3] = random.tmat;

	// Initialize state array:
	for (int i = 1; i < MIN_LOOP; i++) {
		random.state[i & 3] ^= i + (unsigned int)1812433253
			* (random.state[(i - 1) & 3]
				^ (random.state[(i - 1) & 3] >> 30));
	}

	// Generate initial values:
	for (int i = 0; i < PRE_LOOP; i++) {
		tinymt32_next_state();
	}
}

/**
* This function initializes the internal state array with a 32-bit
* unsigned integer seed.
*
* ## Notes
*
* -   See Knuth TAOCP Vol2. 3rd Ed. P.106 for multiplier.
*
* @param init_key  an array of 32-bit unsigned integers
* @param key_length  the length of the array
*/
void init_by_array(const unsigned int *init_key, int key_length) {
	const unsigned int lag = 1;
	const unsigned int mid = 1;
	const unsigned int size = 4;
	unsigned int i, j;
	unsigned int count;
	unsigned int r;
	unsigned int * st = &random.state[0];

	st[0] = 0;
	st[1] = random.mat1;
	st[2] = random.mat2;
	st[3] = random.tmat;
	if (key_length + 1 > MIN_LOOP) {
		count = (unsigned int)key_length + 1;
	} else {
		count = MIN_LOOP;
	}
	r = ini_func1(st[0] ^ st[mid % size]
					^ st[(size - 1) % size]);
	st[mid % size] += r;
	r += (unsigned int)key_length;
	st[(mid + lag) % size] += r;
	st[0] = r;
	count--;
	for (i = 1, j = 0; (j < count) && (j < (unsigned int)key_length); j++) {
		r = ini_func1(st[i % size]
						^ st[(i + mid) % size]
						^ st[(i + size - 1) % size]);
		st[(i + mid) % size] += r;
		r += init_key[j * 2] + i;
		st[(i + mid + lag) % size] += r;
		st[i % size] = r;
		i = (i + 1) % size;
	}
	for (; j < count; j++) {
		r = ini_func1(st[i % size]
						^ st[(i + mid) % size]
						^ st[(i + size - 1) % size]);
		st[(i + mid) % size] += r;
		r += i;
		st[(i + mid + lag) % size] += r;
		st[i % size] = r;
		i = (i + 1) % size;
	}
	for (j = 0; j < size; j++) {
		r = ini_func2(st[i % size]
						+ st[(i + mid) % size]
						+ st[(i + size - 1) % size]);
		st[(i + mid) % size] ^= r;
		r -= i;
		st[(i + mid + lag) % size] ^= r;
		st[i % size] = r;
		i = (i + 1) % size;
	}

	for (i = 0; i < PRE_LOOP; i++) {
		tinymt32_next_state();
	}
}

/**
* This function generates and returns 32-bit unsigned integer.
*
* ## Notes
*
* -   Generates a random number on interval [0,0xffffffff].
*
* @return 32-bit unsigned integer r (0 <= r < 2^32)
*/
unsigned int genrand_int32() {
	tinymt32_next_state();
	return tinymt32_temper();
}

/**
* Generates a random number on the interval `[0,1)` with 53-bit resolution.
*
* ## Notes
*
* -   Added by Isaku Wada (2002/01/09).
*
* @return random number
*/
double genrand_res53() {
	unsigned long a = genrand_int32()>>5;
	unsigned long b = genrand_int32()>>6;
	return ( (a*67108864.0)+b ) * (1.0/9007199254740992.0);
}
